#include <stdio.h>

#define MAX_N 100
#define INF 1000000000

int main(void) {
    int n, m;
    int graph[MAX_N][MAX_N];

    if (scanf("%d %d", &n, &m) != 2) return 0;

    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++)
            graph[i][j] = (i == j) ? 0 : INF;

    for (int i = 0; i < m; i++) {
        int a, b, cost;
        scanf("%d %d %d", &a, &b, &cost);
        a--;
        b--;
        if (cost < graph[a][b]) {
            graph[a][b] = cost;
            graph[b][a] = cost;
        }
    }

    int dist[MAX_N], visited[MAX_N] = {0};
    for (int i = 0; i < n; i++) dist[i] = INF;
    dist[0] = 0;

    for (int i = 0; i < n; i++) {
        int u = -1;
        for (int j = 0; j < n; j++)
            if (!visited[j] && (u == -1 || dist[j] < dist[u]))
                u = j;

        if (u == -1 || dist[u] == INF) break;
        visited[u] = 1;

        for (int v = 0; v < n; v++)
            if (dist[u] + graph[u][v] < dist[v])
                dist[v] = dist[u] + graph[u][v];
    }

    printf("%d\n", dist[n - 1]);
    return 0;
}
